ALTER TABLE inventory_lock ADD COLUMN evidence_model INTEGER NOT NULL DEFAULT 0;
CREATE TRIGGER inventory_evidence_insert BEFORE INSERT ON inventory_entries FOR EACH ROW BEGIN DECLARE active_model INTEGER; SELECT evidence_model INTO active_model FROM inventory_lock WHERE id = 1 FOR UPDATE; IF (NEW.entry_key LIKE 'device/%' OR NEW.entry_key LIKE 'source/%' OR NEW.entry_key LIKE 'alias/%' OR NEW.entry_key LIKE 'serial/%' OR NEW.entry_key LIKE 'serialconflict/%' OR NEW.entry_key LIKE 'field/%' OR NEW.entry_key LIKE 'indexes/%') AND active_model = 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'inventory: retired aggregate write'; END IF; END;
CREATE TRIGGER inventory_evidence_update BEFORE UPDATE ON inventory_entries FOR EACH ROW BEGIN DECLARE active_model INTEGER; SELECT evidence_model INTO active_model FROM inventory_lock WHERE id = 1 FOR UPDATE; IF (NEW.entry_key LIKE 'device/%' OR NEW.entry_key LIKE 'source/%' OR NEW.entry_key LIKE 'alias/%' OR NEW.entry_key LIKE 'serial/%' OR NEW.entry_key LIKE 'serialconflict/%' OR NEW.entry_key LIKE 'field/%' OR NEW.entry_key LIKE 'indexes/%') AND active_model = 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'inventory: retired aggregate write'; END IF; END;
